"""JSON transport for the release planner."""
import json
import sys

from planner import plan


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        result = {"status": "error", "error": "invalid-json", "actions": [], "units": 0}
    else:
        result = plan(request)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

journal.py.text:
"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _is_text(value):
    return isinstance(value, str) and value != ""


def _unit_count(value):
    """Positive integer per SPEC: bools are rejected by the exact type check."""
    return type(value) is int and value >= 1


def read_changes(records):
    """Validate and collapse the change records into replay-stable identities.

    Returns a dict keyed by change id; each value is
    {"component", "units", "depends_on" (list of prerequisite ids)}.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        if (not isinstance(row, dict) or not _is_text(row.get("id"))
                or not _is_text(row.get("component"))
                or not _unit_count(row.get("units"))):
            raise JournalError("invalid-change")
        # Accepts both spellings without loosening anything: `_is_text` (nonempty str)
        # rejects "" and null, and this does not accept bools.
        depends_on = row.get("depends_on", [])
        if not isinstance(depends_on, list) or not all(_is_text(dep) for dep in depends_on):
            raise JournalError("invalid-change")
        change_id = row["id"]
        prior = changes.get(change_id)
        # Identity covers exactly id/component/units/set-of-dependencies. The declared
        # list is kept as given, so a dependency on a nonexistent id still reaches the
        # graph checks and reports `unknown-dependency` rather than being swallowed.
        # Two records with the same id that differ only in order or repetition of the
        # same names are the same change, not a conflict.
        if prior is None:
            changes[change_id] = {"component": row["component"], "units": row["units"],
                                  "depends_on": depends_on}
        elif (prior["component"] != row["component"]
              or prior["units"] != row["units"]
              or set(prior["depends_on"]) != set(depends_on)):
            # Same id, different content can never be replayed safely, even if one
            # copy would be filtered out later; fail closed with no actions.
            raise JournalError("conflicting-change")
        # Exact duplicate: silently collapse. Collapsing here, before accounting and
        # graph construction, is what keeps units from being counted twice.
    return changes


def read_applied(value):
    """Validate the persisted journal supplied by the caller; return a set of ids."""
    if value is None:
        return set()
    if not isinstance(value, list) or not all(_is_text(item) for item in value):
        raise JournalError("invalid-change")
    return set(value)

