    seen = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        # Replay identity: equal id + component + units + dependency *set*. A
        # repeated dependency list in a different order is the same request, but
        # two self-conflicting rows are ambiguous and must fail closed.
        depends_on = frozenset(_read_depends_on(row))
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": depends_on,
        }
        previous = seen.get(row["id"])
        if previous is None:
            seen[row["id"]] = change
            changes.append(change)
        elif previous != change:
            raise JournalError("conflicting-change")
        # Identical duplicate: dropped here, before any accounting or graph work.
    return changes


