    """Fail closed on dangling graph edges or replay entries for unknown IDs.

    Unknown *applied* IDs are rejected even though they never affect ordering:
    they mean the caller's persisted journal disagrees with this request.
    """
    ids = {change["id"] for change in changes}
    for change in changes:
        for dep in change["depends_on"]:
            if dep not in ids:
                raise JournalError("unknown-dependency")
    for entry in applied:
        if entry not in ids:
            raise JournalError("unknown-dependency")
    return ids

