"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, known_ids, read_applied, read_changes, read_retain
from policy import PolicyError, action_for, check_environment, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topological_order(changes):
    """Return every change ID in one deterministic execution order.

    Edges point change -> its dependencies, so in-degree counts unresolved
    dependencies: a change becomes eligible only after all of them are emitted.
    Among currently eligible changes the smallest ID wins (heap), and a heap of
    strings orders Python's code points, matching lexicographic tie-breaking.
    """
    units = {change["id"]: change["units"] for change in changes}
    dependencies = {change["id"]: set(change["depends_on"]) for change in changes}
    dependents = {change["id"]: [] for change in changes}
    pending = {}
    for change in changes:
        pending[change["id"]] = len(change["depends_on"])
        for dep in change["depends_on"]:
            dependents[dep].append(change["id"])
    ready = [cid for cid, count in pending.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        cid = heapq.heappop(ready)
        order.append(cid)
        for dependent in dependents[cid]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heapq.heappush(ready, dependent)
    # Anything left unemitted is on or behind a cycle; fail rather than emit a partial order.
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order, units, dependencies


def retained_ids(retain, dependencies, applied):
    """Expand rollback retain into a closure of applied transitive dependencies.

    Retention must keep every applied change the kept ones need, otherwise a
    rollback would remove a dependency that a retained change still relies on.
    The walk stops at dependencies that were never applied, so this cannot drag
    in installed-or-not IDs beyond what the retained changes actually require.
    """
    kept = set()
    stack = list(retain)
    while stack:
        cid = stack.pop()
        if cid in kept:
            continue
        kept.add(cid)
        for dep in dependencies[cid]:
            if dep in applied and dep not in kept:
                stack.append(dep)
    return kept


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Environment freeze is decided before the entrypoint looks at changes:
        # production must never learn anything from graph or change validation.
        check_environment(request)
        budget = limit_for(request)
        action = action_for(request)
        changes = read_changes(request.get("changes"))
        applied_entries = read_applied(request.get("applied", []))
        known_ids(changes, applied_entries)
        # `retain` is always validated so a malformed field is never silently
        # swallowed; only rollback acts on it.
        retain = read_retain(request.get("retain", []), applied_entries)
        order, units, dependencies = topological_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    # The journal is replay input, not a second source of truth: dedupe applied
    # IDs so replays cannot double count or unlock ordering twice.
    applied = set(applied_entries)
    if action == "plan":
        selected = [cid for cid in order if cid not in applied]
    else:
        # Rollback runs the full order backwards and touches only applied
        # changes; dependencies that were never applied were never installed.
        # Retained IDs plus their applied dependency closure stay installed.
        kept = retained_ids(retain, dependencies, applied)
        selected = [cid for cid in reversed(order) if cid in applied and cid not in kept]

    emitted = sum(units[cid] for cid in selected)
    # Budget is checked against emitted, post-replay work only. Rollback still
    # validates the field but is not capped by it.
    if action == "plan" and emitted > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": selected, "units": emitted}

