"""Validate release policy before computing actions."""

# G2 is staging-only: production requests are frozen for both actions.
PRODUCTION_FROZEN = "production-frozen"
ENVIRONMENTS = {"staging", "production"}
# Staging plans may never spend more than this, whatever the request allows.
STAGING_PLAN_CEILING = 3
SUPPORTED_ACTIONS = {"plan", "rollback"}


class PolicyError(ValueError):
    pass


def check_environment(request):
    """Fail closed on production before any graph or change validation.

    The planner calls this first, so a frozen environment can never leak a
    partial plan or a graph error that would hint at production data.
    """
    if request.get("environment") == "production":
        raise PolicyError(PRODUCTION_FROZEN)
    if request.get("environment") not in ENVIRONMENTS:
        raise PolicyError("invalid-environment")


def limit_for(request):
    """Return the effective plan budget after request validation."""
    check_environment(request)
    # Reject any action outside G2 with the preserved transport code; the
    # budget is still validated below so a bad action never masks bad budget.
    if request.get("action") not in SUPPORTED_ACTIONS:
        raise PolicyError("unsupported-action")
    budget = request.get("budget")
    # `type(...) is not int` (not isinstance) keeps booleans out of budget.
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    # Staging-only release: the owner ceiling trumps a larger request budget.
    # The raw field is still validated first so invalid input keeps its own code.
    if request.get("environment") == "staging":
        return min(budget, STAGING_PLAN_CEILING)
    return budget


def action_for(request):
    """Return the already-validated action; caller must have run limit_for."""
    return request["action"]

